files.content:
:root {
  --pixel-color: #00ff00;
  --bg: #1a1a2e;
  --shadow: #000;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2d2d44;
  font-family: 'Courier New', monospace;
}

.counter {
  background: var(--bg);
  padding: 24px;
  border: 4px solid #0f0f1a;
  box-shadow: 8px 8px 0 0 var(--shadow);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.count {
  min-width: 120px;
  padding: 8px 16px;
  background: #000;
  color: var(--pixel-color);
  font-size: 3rem;
  text-align: center;
  border: 4px solid var(--pixel-color);
  box-shadow: inset -4px -4px 0 #003300, inset 4px 4px 0 #00ff00;
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  background: #e0e0e0;
  border: 4px solid #000;
  padding: 8px 12px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 3px 3px 0 0 #000;
}

.btn:hover {
  background: #ffffff;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 0 #000;
}

.btn:focus-visible {
  outline: 3px solid #ff00ff;
  outline-offset: 2px;
}

let count = 0;
const output = document.getElementById('count');

function updateDisplay() {
  output.textContent = count;
}

document.getElementById('increase').addEventListener('click', () => {
  count += 1;
  updateDisplay();
});

document.getElementById('decrease').addEventListener('click', () => {
  count -= 1;
  updateDisplay();
});

document.getElementById('reset').addEventListener('click', () => {
  count = 0;
  updateDisplay();
});

updateDisplay();
